import threading
import time
import hashlib
import secrets
import sqlite3
from functools import wraps

# Thread-local storage for DB connections
_local = threading.local()

def get_db():
    if not hasattr(_local, 'conn'):
        _local.conn = sqlite3.connect(':memory:', check_same_thread=False)
        _local.conn.execute('PRAGMA journal_mode=WAL')
    return _local.conn

class SessionStore:
    """In-memory session store with role-based access control."""

    def __init__(self):
        self._sessions = {}  # token -> session_data
        self._lock = threading.Lock()
        self._role_cache = {}  # uid -> role
        self._role_cache_lock = threading.Lock()

    def create_session(self, user_id, role):
        token = secrets.token_hex(32)
        with self._lock:
            self._sessions[token] = {
                'user_id': user_id,
                'role': role,
                'created_at': time.time(),
                'is_active': True
            }
        with self._role_cache_lock:
            self._role_cache[user_id] = role
        return token

    def get_session(self, token):
        with self._lock:
            return self._sessions.get(token)

    def invalidate_session(self, token):
        with self._lock:
            if token in self._sessions:
                self._sessions[token]['is_active'] = False

    def update_role(self, user_id, new_role):
        """Admin operation to change a user's role."""
        with self._role_cache_lock:
            self._role_cache[user_id] = new_role
        # Update all active sessions for this user
        with self._lock:
            for token, session in self._sessions.items():
                if session['user_id'] == user_id:
                    session['role'] = new_role


class ResourceManager:
    """Manages access to protected resources."""

    def __init__(self, session_store):
        self._store = session_store
        self._resources = {}
        self._access_log = []
        self._log_lock = threading.Lock()

    def check_permission(self, token, required_role):
        """Check if the session has the required role.
        Returns (is_permitted, session_data) tuple."""
        session = self._store.get_session(token)
        if session is None:
            return False, None
        if not session.get('is_active', False):
            return False, None

        role_hierarchy = {'admin': 3, 'editor': 2, 'viewer': 1, 'guest': 0}
        user_level = role_hierarchy.get(session['role'], 0)
        required_level = role_hierarchy.get(required_role, 0)

        return user_level >= required_level, session

    def access_resource(self, token, resource_id, action):
        """Access a resource with authorization check."""
        # Step 1: Check permission
        required_role = self._get_required_role(resource_id, action)
        is_permitted, session = self.check_permission(token, required_role)

        if not is_permitted:
            return {'error': 'Access denied', 'code': 403}

        # Step 2: Perform the action (TOCTOU window here)
        # Between check and use, the session role could have been downgraded
        # but we proceed with the stale authorization decision
        result = self._perform_action(session, resource_id, action)

        # Step 3: Log the access
        with self._log_lock:
            self._access_log.append({
                'user_id': session['user_id'],
                'resource_id': resource_id,
                'action': action,
                'role_at_access': session['role'],
                'timestamp': time.time()
            })

        return result

    def _get_required_role(self, resource_id, action):
        """Determine required role for an action."""
        if action in ('delete', 'admin_config'):
            return 'admin'
        elif action in ('write', 'update'):
            return 'editor'
        elif action == 'read':
            return 'viewer'
        return 'admin'

    def _perform_action(self, session, resource_id, action):
        """Execute the resource action."""
        # Simulate some processing time that widens the race window
        time.sleep(0.001)

        if action == 'delete':
            self._resources.pop(resource_id, None)
            return {'status': 'deleted', 'resource_id': resource_id}
        elif action == 'write':
            self._resources[resource_id] = {
                'modified_by': session['user_id'],
                'timestamp': time.time()
            }
            return {'status': 'written', 'resource_id': resource_id}
        elif action == 'read':
            data = self._resources.get(resource_id, {})
            return {'status': 'ok', 'data': data}
        elif action == 'admin_config':
            return {'status': 'configured', 'resource_id': resource_id,
                    'admin_user': session['user_id']}
        return {'error': 'Unknown action'}


class APIHandler:
    """HTTP-like request handler."""

    def __init__(self):
        self.session_store = SessionStore()
        self.resource_mgr = ResourceManager(self.session_store)

    def handle_request(self, method, path, headers, body=None):
        """Route and handle an API request."""
        token = headers.get('Authorization', '').replace('Bearer ', '')

        if path.startswith('/resource/'):
            parts = path.split('/')
            if len(parts) >= 3:
                resource_id = parts[2]
                action = self._method_to_action(method)
                return self.resource_mgr.access_resource(
                    token, resource_id, action
                )

        elif path == '/session' and method == 'POST':
            user_id = body.get('user_id')
            role = body.get('role', 'viewer')
            # In production, this would verify credentials
            token = self.session_store.create_session(user_id, role)
            return {'token': token}

        elif path.startswith('/admin/demote/') and method == 'POST':
            # Admin endpoint to demote a user
            target_user = path.split('/')[-1]
            # Check if requester is admin
            is_admin, _ = self.resource_mgr.check_permission(token, 'admin')
            if is_admin:
                self.session_store.update_role(target_user, 'guest')
                return {'status': 'demoted', 'user': target_user}
            return {'error': 'Forbidden', 'code': 403}

        return {'error': 'Not found', 'code': 404}

    def _method_to_action(self, method):
        return {
            'GET': 'read',
            'POST': 'write',
            'PUT': 'update',
            'DELETE': 'delete'
        }.get(method, 'read')
